    // them as-is so the author sees a flat list without a redundant prefix.
    const warning = assetType === "workflow"
        ? `Skipped workflow ${filePath}:\n${detail}`
        : `Skipped malformed ${assetType} asset at ${filePath}: ${detail}`;
